// CAMERA (rotates around the y axis)
const vec3 cameraOrigin = vec3(0.0, 0.0, -5.0);

// LIGHT
const vec3 lightAxis = normalize(vec3(1.0, 1.0, 1.0));
const vec3 purple = vec3(0.6, 0.2, 1.0);

// SPHERE
const vec3 sphereCenter = vec3(0.0, 0.0, 0.0);
const float sphereRadius = 1.0;
const float sphereRadiusSquared = sphereRadius * sphereRadius;

// CYLINDER
const vec3 cylinderCenter = vec3(0.5, 0.0, 0.0);
const float cylinderRadius = 1.0;
const float cylinderRadiusSquared = cylinderRadius * cylinderRadius;
const mat3 cylinderAxis = mat3(normalize(vec3(1.0, 0.0, 0.0)),
                               normalize(vec3(0.0, 1.0, 0.5)),
                               normalize(vec3(0.0, -0.5, 1.0)));

// const float cylinderHeight = 2.0;

// PLANE
const vec3 planeNormal = normalize(vec3(0.0, 0.0, 1.0));
const vec3 planeCenter = vec3(0.0, 0.0, 0.0);
const vec3 planeCheckerboardX = normalize(vec3(-1.0, 0.5, 0.0));
const vec3 planeCheckerboardY = normalize(vec3(0.5, 1.0, 0.0));
const vec2 planeSize = vec2(2.0, 3.0);

// CUBE
const vec3 cubeCenter = vec3(0.5, 0.0, 0.0);
// const float cubeSide = 1.0;
const mat3 cubeAxis = mat3(normalize(vec3(-1.0, 0.0, 0.0)),
                           normalize(vec3(0.0, 1.0, -10.0)),
                           normalize(vec3(0.0, 10.0, 1.0)));

// OTHER
const float delta = 1e-6;

/* utils */

vec3 projectVectorUsingNormal(vec3 vector, vec3 planeNormal) {
    float normalComponent = dot(vector, planeNormal);
    return vector - normalComponent * planeNormal;
}

// Solve ax + b = 0, return true if a positive solution exists.
bool linearEquation(float a, float b, out float positiveSolution) {
    if (abs(a) < delta && abs(b) > delta) {
        return false;
    } else {
        positiveSolution = - b / a;
        return (positiveSolution >= 0.0);
    }
}

// Solve |ax + b| <= 1, return true if a positive solution exists.
bool absLinearInequation(float a, float b, out float meanSolution, out float solutionHalfDistance) {
    if (abs(a) < delta) {
        return (abs(b) <= 1.0);
    }
    meanSolution = - b / a;
    solutionHalfDistance = abs(1.0 / a);
    return (meanSolution + solutionHalfDistance >= 0.0);
}

// Solve ax^2 + bx + c = 0, return true if a positive solution exists.
bool quadraticEquation(float a, float b, float c, out float meanSolution, out float solutionHalfDistance) {
    float b2Minus4ac = b * b - 4.0 * a * c;
    if (b2Minus4ac < 0.0) { return false; }

    meanSolution = - b / (2.0 * a);
    solutionHalfDistance = sqrt(b2Minus4ac) / abs(2.0 * a);
    return (meanSolution + solutionHalfDistance >= 0.0);
}

/* 2d */

bool ri2dCircle(vec3 rayToCenter, vec3 rayDirection, float radiusSquared, out vec3 normal) {
    float b = -2.0 * dot(rayToCenter, rayDirection);
    float c = dot(rayToCenter, rayToCenter) - radiusSquared;

    float meanSolution, solutionHalfDistance;
    bool visibleIntersection = quadraticEquation(1.0, b, c, meanSolution, solutionHalfDistance);

    if (visibleIntersection) {
        float minimalPositiveSolution = meanSolution - solutionHalfDistance;
        if (minimalPositiveSolution < 0.0) {
            minimalPositiveSolution += 2.0 * solutionHalfDistance;
        }
        normal = normalize(minimalPositiveSolution * rayDirection - rayToCenter);
    }
    return visibleIntersection;
}


/* 3d */

bool riSphere(vec3 origin, vec3 direction, out vec3 normal) {
    vec3 rayToCenter = sphereCenter - origin;

    return ri2dCircle(rayToCenter, direction, sphereRadiusSquared, normal);
}

bool riInfiniteCylinder(vec3 origin, vec3 direction, out vec3 normal) {
    // projection in the plane orthonogal to cylinderAxis
    vec3 projectedHypotenuse = projectVectorUsingNormal(cylinderCenter - origin, cylinderAxis[0]);
    vec3 projectedDirection = normalize(projectVectorUsingNormal(direction, cylinderAxis[0]));

    return ri2dCircle(projectedHypotenuse, projectedDirection, cylinderRadiusSquared, normal);
}

bool riCheckerboardPlane(vec3 origin, vec3 direction, out vec3 normal) {
    vec3 rayToCenter = planeCenter - origin;
    float a = dot(direction, planeNormal);
    float b = -dot(rayToCenter, planeNormal);

    normal = planeNormal;

    float distanceToIntersection;
    bool visibleIntersection = linearEquation(a, b, distanceToIntersection);

    // draw checkerboard
    if (visibleIntersection) {
        vec3 intersectionCoordinates = -rayToCenter + distanceToIntersection * direction;
        vec2 inPlaneCoordinates = vec2(dot(intersectionCoordinates, planeCheckerboardX),
                                       dot(intersectionCoordinates, planeCheckerboardY));
        inPlaneCoordinates = floor(mod(inPlaneCoordinates, 2.0));
        if (inPlaneCoordinates.x == inPlaneCoordinates.y) {
            normal *= 0.7;
        }
    }
    return visibleIntersection;

}

bool riFinitePlane(vec3 origin, vec3 direction, out vec3 normal) {
    vec3 rayToCenter = planeCenter - origin;
    float a = dot(direction, planeNormal);
    float b = -dot(rayToCenter, planeNormal);

    normal = planeNormal;

    float distanceToIntersection;
    bool visibleIntersection = linearEquation(a, b, distanceToIntersection);

    // draw only visible rectangle
    if (visibleIntersection) {
        vec3 intersectionCoordinates = -rayToCenter + distanceToIntersection * direction;
        vec2 inPlaneCoordinates = vec2(dot(intersectionCoordinates, planeCheckerboardX),
                                       dot(intersectionCoordinates, planeCheckerboardY));
        if (any(greaterThan(abs(inPlaneCoordinates), planeSize))) {
            normal *= 0.0;
        }
    }
    return visibleIntersection;
}

bool riCube(vec3 origin, vec3 direction, out vec3 normal) {
    // convert coordinates to cube coordinates
    vec3 newOrigin = cubeAxis * (origin - cubeCenter);
    vec3 newDirection = cubeAxis * direction;

    vec3 meanSolution;
    vec3 solutionHalfDistance;
    // The cube is an intersection of 3 planes.
    // If the light ray doesn't intersect one of these planes
    // in front of the camera, then return false.
    for (int i = 0; i < 3; i++) {
        if (!absLinearInequation(newDirection[i], newOrigin[i], meanSolution[i],
                                 solutionHalfDistance[i])) {
            return false;
        }
    }

    // Now check that the light ray intersects the 3 planes
    // at the same time.
    vec3 maximumSolution = meanSolution + solutionHalfDistance;
    vec3 minimumSolution = meanSolution - solutionHalfDistance;

    float maximum = min(min(maximumSolution.x, maximumSolution.y), maximumSolution.z);
    float minimum = max(max(minimumSolution.x, minimumSolution.y), minimumSolution.z);

    bool intersection = (minimum <= maximum);

    // what about the signs !!!??
    if (intersection) {
        if (minimum < 0.0) {
            if (maximum == maximumSolution[0]) {
                normal = cubeAxis[0];
            } else if (maximum == maximumSolution[1]) {
                normal = cubeAxis[1];
            } else {
                normal = cubeAxis[2];
            }
        } else {
            if (minimum == minimumSolution[0]) {
                normal = cubeAxis[0];
            } else if (minimum == minimumSolution[1]) {
                normal = cubeAxis[1];
            } else {
                normal = cubeAxis[2];
            }
        }
    }
    return intersection;
}

bool riCylinder(vec3 origin, vec3 direction, out vec3 normal) {
    // convert coordinates to cylinder coordinates
    vec3 newOrigin = cylinderAxis * (origin - cylinderCenter);
    vec3 newDirection = cylinderAxis * direction;

    vec2 meanSolution;
    vec2 solutionHalfDistance;
    // The cylinder is an intersection of a plane
    // and an infinite cylinder
    if (!absLinearInequation(newDirection[0], newOrigin[0], meanSolution[0],
                             solutionHalfDistance[0])) {
        return false;
    }

    vec3 rayToCenter = projectVectorUsingNormal(cylinderCenter - origin, cylinderAxis[0]);
    vec3 rayDirection = projectVectorUsingNormal(direction, cylinderAxis[0]);
    float a = dot(rayDirection, rayDirection);
    float b = -2.0 * dot(rayToCenter, rayDirection);
    float c = dot(rayToCenter, rayToCenter) - cylinderRadiusSquared;

    bool visibleCircle = quadraticEquation(a, b, c, meanSolution[1], solutionHalfDistance[1]);

    vec3 circleNormal;
    if (visibleCircle) {
        float minimalPositiveSolution = meanSolution[1] - solutionHalfDistance[1];
        if (minimalPositiveSolution < 0.0) {
            minimalPositiveSolution += 2.0 * solutionHalfDistance[1];
        }
        circleNormal = normalize(minimalPositiveSolution * rayDirection - rayToCenter);
    } else {
        return false;
    }

    // Now check that the light ray intersects the 2 objects
    // at the same time.
    vec2 maximumSolution = meanSolution + solutionHalfDistance;
    vec2 minimumSolution = meanSolution - solutionHalfDistance;

    float maximum = min(maximumSolution.x, maximumSolution.y);
    float minimum = max(minimumSolution.x, minimumSolution.y);

    bool intersection = (minimum <= maximum);

    // careful, the signs aren't computed
    if (intersection) {
        if (minimum < 0.0) {
            if (maximum == maximumSolution[0]) {
                normal = cylinderAxis[0];
            } else {
                normal = circleNormal;
            }
        } else {
            if (minimum == minimumSolution[0]) {
                normal = cylinderAxis[0];
            } else {
                normal = circleNormal;
            }
        }
    }
    return intersection;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Camera setup
    vec3 ro = cameraOrigin;
    vec3 rd = normalize(vec3(uv.x, uv.y, 1.0));

    if (true) {
        // Rotate camera around z axis
        float angle = iTime;
        rd.xz = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * rd.xz;
        ro.xz = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * ro.xz;
    } else {
        // Go towards center
        ro -= ro / 10.0 * iTime;
    }

    // Raytracing
    vec3 color = vec3(0.0);
    // riCube, riCylinder, riSphere, riCheckerboardPlane, riFinitePlane, riInfiniteCylinder
    vec3 weightedNormal;
    if (riCylinder(ro, rd, weightedNormal)) {
        float brightness = abs(dot(weightedNormal, lightAxis));
        color = purple * brightness;

        // normal map :
        // color = abs(weightedNormal);

        // intersection :
        // color = vec3(1.0);
    }

    fragColor = vec4(color, 1.0);
}
